import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c5b4a')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc-billing', 'billing@corp.internal', 'service', 'sk-billing-1a2b3c4d5e6f')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (3, 'john.doe', 'john@example.com', 'user', 'sk-user-aabbccddee')")
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username or email. Supports partial matching."""
    query_param = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Basic input length check
    if len(query_param) > 100:
        return jsonify({'error': 'Query too long'}), 400

    # Restrict searchable fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query with user input for flexible searching
    sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{query_param}%'"

    try:
        db = get_db()
        cursor = db.execute(sql)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search for compliance
        db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
                   ('user_search', f'field={field}, q={query_param[:50]}'))
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID. API key is only shown to admins."""
    auth_key = request.headers.get('X-API-Key', '')
    db = get_db()

    # Check if requester is admin
    requester = db.execute("SELECT role FROM users WHERE api_key = ?", (auth_key,)).fetchone()
    is_admin = requester and requester['role'] == 'admin'

    user = db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404

    result = {'id': user['id'], 'username': user['username'], 'email': user['email'], 'role': user['role']}
    if is_admin:
        result['api_key'] = user['api_key']

    return jsonify(result)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
